'''+styles+'''const normalizeNavigationPath = (url: string) =>
  url.split(/[?#]/)[0].replace(/\\/+$/, "");

const isNavigationActive = (path: string | null, url: string) => {
  if (path === null) return false;
  const currentPath = normalizeNavigationPath(path);
  const targetPath = normalizeNavigationPath(url);
  return (
    currentPath === targetPath ||
    (targetPath !== "" && currentPath.startsWith(`${targetPath}/`))
  );
};

const hasActiveChild = (link: NavigationLink, path: string | null) =>
  !!link.children?.some(
    (child) => child.visibility !== false && isNavigationActive(path, child.url),
  );

export interface NavigationLink {
  header?: string;
  headerIcon?: ReactNode;
  name: string;
  url: string;
  icon?: ReactNode;
  visibility?: boolean;
  children?: NavigationLink[];
}

interface NavLinkProps {
  href: string;
  ariaLabel: string;
  isActive: boolean;
  className?: string;
  onClick?: () => void;
  children: ReactNode;
}

function NavLink({
  href,
  ariaLabel,
  isActive,
  className,
  onClick,
  children,
}: NavLinkProps) {
  const { isMobile, setOpenMobile } = useSidebar();

  return (
    <Link
      href={href}
      basePath="/"
      aria-label={ariaLabel}
      aria-current={isActive ? "page" : undefined}
      data-active={isActive}
      className={className}
      onClick={(event) => {
        // Preserve native open-in-new-tab/window behavior.
        if (
          event.defaultPrevented ||
          event.button !== 0 ||
          event.metaKey ||
          event.ctrlKey ||
          event.shiftKey ||
          event.altKey
        ) {
          return;
        }

        const current = window.location;
        const isSelected = /[?#]/.test(href)
          ? href === `${current.pathname}${current.search}${current.hash}`
          : normalizeNavigationPath(href) === normalizeNavigationPath(current.pathname);

        if (isSelected) {
          event.preventDefault();
          if (isMobile) setOpenMobile(false);
        }
        onClick?.();
      }}
    >
      {children}
    </Link>
  );
}

interface NavMainProps {
  links: NavigationLink[];
  label?: string;
}

export function NavMain({ links, label }: NavMainProps) {
  const { state, isMobile } = useSidebar();
  const isCollapsed = state === "collapsed" && !isMobile;
  const path = usePath();

  return (
    <SidebarGroup className="gap-0.5 py-2">
      {label && (
        <SidebarGroupLabel className="font-medium text-neutral-600 uppercase">
          {label}
        </SidebarGroupLabel>
      )}
      <SidebarMenu className="gap-0.5">
        {links
          .filter((link) => link.visibility !== false)
          .map((link) =>
            link.children ? (
              isCollapsed ? (
                <SidebarMenuItem key={link.name}>
                  <PopoverMenu link={link} path={path} />
                </SidebarMenuItem>
              ) : (
                <CollapsibleNavItem key={link.name} link={link} path={path} />
              )
            ) : (
              <SidebarMenuItem key={link.name}>
                <SidebarMenuButton
                  asChild
                  tooltip={link.name}
                  isActive={isNavigationActive(path, link.url)}
                  className={CAREUI_NAV_CLASSES}
                >
                  <NavLink
                    href={link.url}
                    ariaLabel={link.name}
                    isActive={isNavigationActive(path, link.url)}
                  >
                    {link.icon ?? (
                      <Avatar name={link.name} className="size-6 -m-1 rounded-sm" />
                    )}
                    <span className="group-data-[collapsible=icon]:hidden" title={link.name}>
                      {link.name}
                    </span>
                  </NavLink>
                </SidebarMenuButton>
              </SidebarMenuItem>
            ),
          )}
      </SidebarMenu>
    </SidebarGroup>
  );
}

interface NavGroupProps {
  link: NavigationLink;
  path: string | null;
}

function CollapsibleNavItem({ link, path }: NavGroupProps) {
  const childActive = hasActiveChild(link, path);
  const [storedState, handleOpenChange] = useAtom(navExpansionAtom(link.name));
  const isOpen = storedState ?? childActive;

  useEffect(() => {
    if (childActive) handleOpenChange(true);
  }, [path, childActive, handleOpenChange]);

  return (
    <Collapsible
      asChild
      open={isOpen}
      onOpenChange={handleOpenChange}
      className="group/collapsible"
    >
      <SidebarMenuItem>
        <CollapsibleTrigger asChild>
          <SidebarMenuButton
            aria-label={link.name}
            tooltip={link.name}
            isActive={childActive && !isOpen}
            className={cn(
              CAREUI_NAV_CLASSES,
              "cursor-pointer",
              childActive && isOpen && "font-medium text-emerald-800",
            )}
          >
            {link.icon ?? (
              <Avatar name={link.name} className="size-6 -m-1 rounded-sm" />
            )}
            <span className="truncate" title={link.name}>{link.name}</span>
            <ChevronRight className="ml-auto transition-transform duration-200 group-data-[state=open]/collapsible:rotate-90 motion-reduce:transition-none" />
          </SidebarMenuButton>
        </CollapsibleTrigger>
        <CollapsibleContent>
          <SidebarMenuSub className="gap-0.5 border-l border-neutral-300">
            {link.children
              ?.filter((child) => child.visibility !== false)
              .map((subItem) => (
                <SidebarMenuSubItem key={subItem.name}>
                  <NavGroupHeading item={subItem} />
                  <SidebarMenuSubButton
                    asChild
                    isActive={isNavigationActive(path, subItem.url)}
                    className={CAREUI_NAV_CLASSES}
                  >
                    <NavLink
                      href={subItem.url}
                      ariaLabel={subItem.name}
                      isActive={isNavigationActive(path, subItem.url)}
                      className="w-full"
                    >
                      <span className="truncate" title={subItem.name}>
                        {subItem.name}
                      </span>
                    </NavLink>
                  </SidebarMenuSubButton>
                </SidebarMenuSubItem>
              ))}
          </SidebarMenuSub>
        </CollapsibleContent>
      </SidebarMenuItem>
    </Collapsible>
  );
}

function NavGroupHeading({ item }: { item: NavigationLink }) {
  if (!item.header) return null;
  return (
    <div className="mt-2 flex items-center gap-2">
      {item.headerIcon}
      <span className="text-xs font-medium text-neutral-600 uppercase">
        {item.header}
      </span>
    </div>
  );
}

function PopoverMenu({ link, path }: NavGroupProps) {
  const [open, setOpen] = useState(false);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <SidebarMenuButton
          aria-label={link.name}
          tooltip={link.name}
          isActive={hasActiveChild(link, path)}
          className={cn(CAREUI_NAV_CLASSES, "cursor-pointer")}
        >
          {link.icon ?? (
            <Avatar name={link.name} className="size-6 -m-1 rounded-sm" />
          )}
        </SidebarMenuButton>
      </PopoverTrigger>
      <PopoverContent
        side="right"
        align="start"
        className="w-60 max-h-(--radix-popover-content-available-height) overflow-y-auto rounded-xl border-neutral-200 bg-white p-1 text-neutral-950 shadow-md"
        aria-label={link.name}
      >
        <div className="flex flex-col gap-0.5">
          {link.children
            ?.filter((item) => item.visibility !== false)
            .map((subItem) => (
              <Fragment key={subItem.name}>
                <NavGroupHeading item={subItem} />
                <NavLink
                  href={subItem.url}
                  ariaLabel={subItem.name}
                  isActive={isNavigationActive(path, subItem.url)}
                  className={cn(CAREUI_NAV_CLASSES, "flex w-full shrink-0 items-center outline-hidden")}
                  onClick={() => setOpen(false)}
                >
                  <span className="truncate" title={subItem.name}>{subItem.name}</span>
                </NavLink>
              </Fragment>
            ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}
